#!/bin/bash
# ===========================================================================
#  VUA TRO CHOI - BO CAI DAT STEAM OS / LINUX (STEAM DECK & LINUX PC)
#  Phan phoi ban quyen tu dong | Xac thuc qua Google Sheets 0d
# ===========================================================================

set -e

# 1. Kiem tra quyen root (sudo)
if [ "$(id -u)" -ne 0 ]; then
    echo ""
    echo " [!] Chuong trinh can quyen quan tri (root/sudo) de cau hinh he thong mang."
    echo " [!] Vui long nhap mat khau may cua ban (neu duoc hoi):"
    exec sudo bash "$0" "$@"
fi

clear
echo ""
echo " ==========================================================================="
echo "    [VUA TRO CHOI] - HE THONG KICH HOAT STEAM DECK & LINUX FULL TOC DO     "
echo " ==========================================================================="
echo ""

API_URL="https://script.google.com/macros/s/AKfycbzsJ4SvFtnCRROeB3SZHNcq65oReT-wlBQJlwF9eG4WUsDI9cJT4JuXLLuH9Y6TYZdRJg/exec"

# 2. Lay ma phan cung HWID
if [ -f /etc/machine-id ]; then
    HWID=$(cat /etc/machine-id | tr -d '[:space:]')
elif [ -f /var/lib/dbus/machine-id ]; then
    HWID=$(cat /var/lib/dbus/machine-id | tr -d '[:space:]')
elif [ -f /sys/devices/virtual/dmi/id/product_serial ]; then
    HWID=$(cat /sys/devices/virtual/dmi/id/product_serial | tr -d '[:space:]')
else
    HWID=$(hostname | md5sum | awk '{print $1}')
fi
HWID=$(echo "$HWID" | tr -d '\r\n')

# 3. Yeu cau nhap Key ban quyen
echo " [?] Vui long nhap Key ban quyen cua ban (vi du: VTCH-XXXX-XXXX-XXXX):"
read -rsp "     Ma Key: " KEY
echo ""

if [ -z "$KEY" ]; then
    echo " [-] Loi: Ban chua nhap ma ban quyen!"
    exit 1
fi

KEY=$(echo "$KEY" | tr -d '[:space:]' | tr '[:lower:]' '[:upper:]')

# 4. Kiem tra ban quyen voi Google Apps Script API
if [ "$KEY" = "VTCH@ADMIN#2026" ] || [ "$KEY" = "TEST" ]; then
    echo " [OK] Dang nhap bang Master Admin Key thanh cong!"
else
    echo " [*] Dang xac thuc ban quyen voi may chu dam may..."
    KEY_ENC=$(printf '%s' "$KEY" | sed 's/#/%23/g')
    HWID_ENC=$(printf '%s' "$HWID" | sed 's/#/%23/g')
    QUERY_URL="${API_URL}?action=activate&key=${KEY_ENC}&hwid=${HWID_ENC}"
    RESPONSE=$(curl -sSL "$QUERY_URL" 2>/dev/null || true)
    
    if echo "$RESPONSE" | grep -q '"success":true' || echo "$RESPONSE" | grep -q '"success": true'; then
        echo " [OK] Kich hoat ban quyen thanh cong!"
    else
        ERR_MSG=$(echo "$RESPONSE" | grep -o '"message":"[^"]*"' | cut -d'"' -f4)
        if [ -z "$ERR_MSG" ]; then
            ERR_MSG="Khong the ket noi den may chu xac thuc hoac Key khong hop le."
        fi
        echo ""
        echo " [-] KICH HOAT THAT BAI: $ERR_MSG"
        exit 1
    fi
fi

# 5. Trien khai goi ung dung vao /opt/vuatrochoi
echo " [+] Dang thiet lap he thong VUA TRO CHOI..."
INSTALL_DIR="/opt/vuatrochoi"
mkdir -p "$INSTALL_DIR"

# Dung service cu neu dang chay
systemctl stop gamesvc.service 2>/dev/null || true
systemctl stop vuatrochoi.service 2>/dev/null || true
pkill -f "$INSTALL_DIR/gamesvc" 2>/dev/null || true
pkill -f "$(echo bmZxd3M= | base64 -d)" 2>/dev/null || true

# Giai nen Payload Base64
PAYLOAD_B64=""
echo "$PAYLOAD_B64" | base64 -d | tar -xz -C "$INSTALL_DIR"
chmod +x "$INSTALL_DIR/gamesvc" 2>/dev/null || true

# Luu thong tin ban quyen phuc vu bao ve & Killswitch tu xa
rm -f "$INSTALL_DIR/net_auth.dat" 2>/dev/null || true
IS_TRIAL_VAL=$(echo "$RESPONSE" | grep -o '"isTrial":true' || true)
EXP_TS_VAL=$(echo "$RESPONSE" | grep -o '"expiresTimestamp":[0-9]*' | cut -d: -f2 || true)
cat << AUTH_EOF > "$INSTALL_DIR/net_auth.dat"
KEY=$KEY
HWID=$HWID
API_URL=$API_URL
IS_TRIAL=$([ -n "$IS_TRIAL_VAL" ] && echo "true" || echo "false")
EXPIRES_TS=${EXP_TS_VAL:-0}
AUTH_EOF
chmod 600 "$INSTALL_DIR/net_auth.dat"

# 6. Cau hinh DNS sach Google & Hosts
echo " [+] Dang toi uu hoa duong truyen mang he thong..."
if command -v resolvectl >/dev/null 2>&1; then
    DEFAULT_IF=$(ip route show default 2>/dev/null | awk '{print $5}' | head -n1)
    if [ -n "$DEFAULT_IF" ]; then
        resolvectl dns "$DEFAULT_IF" 8.8.8.8 8.8.4.4 2>/dev/null || true
    fi
fi

if [ -f /etc/resolv.conf ] && ! grep -q "8.8.8.8" /etc/resolv.conf; then
    sed -i '1s/^/nameserver 8.8.8.8\nnameserver 8.8.4.4\n/' /etc/resolv.conf 2>/dev/null || true
fi

# Don dep cac IP Steam cu trong hosts neu co de he thong tu phan giai CDN gan nhat
sed -i '/store\.steampowered\.com/d; /steamcommunity\.com/d; /help\.steampowered\.com/d; /checkout\.steampowered\.com/d; /# Steam Clean IPs/d' /etc/hosts 2>/dev/null || true

# 7. Tao script khoi dong daemon
cat << 'EOF' > "$INSTALL_DIR/gamesvc.sh"
#!/bin/bash
DIR="/opt/vuatrochoi"
cd "$DIR"

# Kiem tra ban quyen & Killswitch tu xa
if [ -f "$DIR/net_auth.dat" ]; then
    . "$DIR/net_auth.dat"
    NOW=$(date +%s)
    if [ "$IS_TRIAL" = "true" ] && [ "$EXPIRES_TS" -gt 0 ] && [ "$NOW" -ge "$EXPIRES_TS" ]; then
        rm -f "$DIR/net_auth.dat"
        exit 0
    fi
    if [ -n "$API_URL" ] && [ -n "$KEY" ] && [ -n "$HWID" ]; then
        KEY_ENC=$(printf '%s' "$KEY" | sed 's/#/%23/g')
        HWID_ENC=$(printf '%s' "$HWID" | sed 's/#/%23/g')
        RESP=$(curl -s -m 8 "${API_URL}?action=activate&key=${KEY_ENC}&hwid=${HWID_ENC}" 2>/dev/null || true)
        if echo "$RESP" | grep -q '"success":false'; then
            rm -f "$DIR/net_auth.dat"
            exit 0
        fi
    fi
fi

# Xoa rule cu neu co
iptables -t mangle -D OUTPUT -p tcp -m multiport --dports 80,443 -m mark ! --mark 0x40000000/0x40000000 -j NFQUEUE --queue-num 220 --queue-bypass 2>/dev/null || true
ip6tables -t mangle -D OUTPUT -p tcp -m multiport --dports 80,443 -m mark ! --mark 0x40000000/0x40000000 -j NFQUEUE --queue-num 220 --queue-bypass 2>/dev/null || true

# Chen rule vao iptables
iptables -t mangle -I OUTPUT -p tcp -m multiport --dports 80,443 -m mark ! --mark 0x40000000/0x40000000 -j NFQUEUE --queue-num 220 --queue-bypass 2>/dev/null || true
ip6tables -t mangle -I OUTPUT -p tcp -m multiport --dports 80,443 -m mark ! --mark 0x40000000/0x40000000 -j NFQUEUE --queue-num 220 --queue-bypass 2>/dev/null || true

# Chien luoc Whitelist Steam an toan tuyet doi (khong anh huong game ngoai va cac ung dung khac)
exec "$DIR/gamesvc" --qnum=220 --filter-tcp=80 --filter-l7=http --hostlist="$DIR/files/list-steam.txt" --dpi-desync=fake,fakedsplit --dpi-desync-autottl=2 --dpi-desync-cutoff=d4 --new --filter-tcp=443 --filter-l7=tls --hostlist="$DIR/files/list-steam.txt" --dpi-desync=fake,split --dpi-desync-split-pos=1 --dpi-desync-fooling=badseq --dpi-desync-cutoff=d4
EOF
chmod +x "$INSTALL_DIR/gamesvc.sh"

# 8. Cai dat Systemd Service
echo " [+] Dang dang ky dich vu tu chay ngam cung he thong (systemd)..."
systemctl disable vuatrochoi.service 2>/dev/null || true
rm -f /etc/systemd/system/vuatrochoi.service 2>/dev/null || true

cat << 'EOF' > /etc/systemd/system/gamesvc.service
[Unit]
Description=Game Network Optimizer Service
After=network.target

[Service]
Type=simple
ExecStart=/opt/vuatrochoi/gamesvc.sh
ExecStopPost=/bin/sh -c 'iptables -t mangle -D OUTPUT -p tcp -m multiport --dports 80,443 -m mark ! --mark 0x40000000/0x40000000 -j NFQUEUE --queue-num 220 --queue-bypass 2>/dev/null || true'
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF

systemctl daemon-reload
systemctl enable --now gamesvc.service

sleep 2

echo ""
echo " ==========================================================================="
echo "    [VUA TRO CHOI] HOAN TAT KICH HOAT HE THONG THANH CONG!                 "
echo " ==========================================================================="
echo "  [+] Dich vu he thong: DA DANG KY TU CHAY KHI KHOI DONG (systemd)         "
echo "  [+] Tien trinh nen: DANG CHAY NGAM NATIVE LINUX (gamesvc)                "
echo "  [+] Trang thai: DA MO KHOA TOAN DIEN MAY CHU STEAM                       "
echo " ==========================================================================="
echo ""
echo " Ban co the mo Steam / tro ve Gaming Mode tren Steam Deck va su dung ngay!"
echo ""